gold_response:
IMAGE ambient_bottle "药瓶" x=80 y=420 w=96 h=120 z=5 vis=true
MOVE ambient_bottle 360 280 ms=2200 keep=true
STYLE ambient_bottle {"alpha":0.65,"scale":0.9}

candidate:
VAR score = 0 temporary=false
TEXT score_text "得分：{score}" x=20 y=20 z=10
TEXT title "答题闯关（答对3题通关）" x=220 y=20 z=10
TEXT q1 "1. 1+1等于几？" x=50 y=80 z=5
BUTTON b11 "2" x=50 y=120 z=5
BUTTON b12 "3" x=150 y=120 z=5
CLICK b11 action=commands
    VAR score + 1
    STYLE b11 {"display":"none"}
    STYLE b12 {"display":"none"}
    IF score >= 3
        SIGNAL passed
TEXT q2 "2. 中国的首都是哪里？" x=50 y=200 z=5
BUTTON b21 "北京" x=50 y=240 z=5
BUTTON b22 "上海" x=150 y=240 z=5
CLICK b21 action=commands
    VAR score + 1
    STYLE b21 {"display":"none"}
    STYLE b22 {"display":"none"}
    IF score >= 3
        SIGNAL passed
TEXT q3 "3. 太阳从哪边升起？" x=50 y=320 z=5
BUTTON b31 "东方" x=50 y=360 z=5
BUTTON b32 "西方" x=150 y=360 z=5
CLICK b31 action=commands
    VAR score + 1
    STYLE b31 {"display":"none"}
    STYLE b32 {"display":"none"}
    IF score >= 3
        SIGNAL passed
ON passed "通关"
    STYLE title {"display":"none"}
    STYLE score_text {"display":"none"}
    STYLE q1 {"display":"none"}
    STYLE b11 {"display":"none"}
    STYLE b12 {"display":"none"}
    STYLE q2 {"display":"none"}
    STYLE b21 {"display":"none"}
    STYLE b22 {"display":"none"}
    STYLE q3 {"display":"none"}
    STYLE b31 {"display":"none"}
    STYLE b32 {"display":"none"}
    TEXT result "恭喜通关！" x=300 y=260 block=true dismiss=true
    ANIM_IN result scaleIn ms=800
    NEXT
